    valid = (q >= qmnf) & (q <= qmxf)
    qc = tl.minimum(tl.maximum(q, qmnf), qmxf)
    out = (qc - z) * s
    tl.store(out_ptr + off, out, mask=m)
    tl.store(mask_ptr + off, valid.to(tl.int8), mask=m)


