def _fused_moving_avg_obs_fq_helper(
    self,
    observer_on,
    fake_quant_on,
    running_min,
    running_max,
    scale,
    zero_point,
    averaging_const,
    quant_min,
    quant_max,
    ch_axis,
    per_row_fake_quant=False,
    symmetric_quant=False,
):
    """Fused moving-average observer + fake-quantize helper (QAT).

    Matches aten._fused_moving_avg_obs_fq_helper: updates running_min/max in
    place by moving average, recomputes scale/zero_point, and fake-quantizes
    the input. Supports per-tensor and per-channel (per_row_fake_quant) modes.
    Returns (output, mask); running_min/max/scale/zero_point are updated in
    place to match the native op's mutating contract.
    """
    logger.debug("GEMS _FUSED_MOVING_AVG_OBS_FQ_HELPER")
    # The native ATen operator is intentionally restricted to float32 input.
    # Keep this check at the dispatch boundary instead of silently converting
    # unsupported inputs, which would make FlagGems diverge from ATen.
    if self.dtype is not torch.float32:
        scalar_type = _SCALAR_TYPE_NAMES.get(self.dtype, str(self.dtype))
        raise RuntimeError(f"expected scalar type Float but found {scalar_type}")

    x = self
    dev = x.device
    obs = int(observer_on)
    fq = int(fake_quant_on)
    sym = bool(symmetric_quant)
    pc = bool(per_row_fake_quant)
    qmin = int(quant_min)
    qmax = int(quant_max)
    ac = float(averaging_const)

    N = x.numel()
    xf = x.contiguous().view(-1)

    if pc:
        C = x.shape[int(ch_axis)]
        R = N // C
    else:
        C = 1
        R = N

    out = torch.empty_like(xf, dtype=torch.float32)
    mask_b = torch.empty(N, dtype=torch.bool, device=dev)

    # Fused fake-quant-on path: single launch for qparam + fake-quant (removes
    # the separate _qparams launch) for BOTH per-tensor and per-channel. Each
    # lane recomputes its channel's scale/zp from read-only inputs; the lane at
    # each channel's first element persists that channel's qparam/running stats.
